import sys
from collections import Counter

def main():
    data = sys.stdin.read().split()
    if len(data) < 2:
        return
    p, a = data[0], data[1]

    cp = Counter(p)
    ca = Counter(a.replace('*', ''))

    for ch, cnt in ca.items():
        if cp[ch] < cnt:
            print('N')
            return

    print('S')

if __name__ == "__main__":
    main()
